mapper.select:
SELECT id, full_name, email, phone, status, created_at
FROM customers

    deleted_at IS NULL
    AND status=#{status}
    AND (full_name ILIKE CONCAT('%',#{keyword},'%') OR email ILIKE CONCAT('%',#{keyword},'%') OR phone ILIKE CONCAT('%',#{keyword},'%'))

ORDER BY created_at DESC LIMIT #{limit} OFFSET #{offset}
